-- DEMO SEED DATA for the Rocket Rally site. Generated by a one-off
-- script that was not kept — hand-edit or regenerate as needed, keeping
-- classroom/priority ids in sync with site/js/data.js.
-- Prototype-style numbers on the real 2026 roster: $38,275 in 311 family
-- gifts plus $3,000 from four online partners = $41,275 of the
-- $50,000 goal; the gifts credit 328 Rockets (65% participation); fee cover
-- on about 70% of gifts.
-- Apply:  npx wrangler d1 execute red-hill-rally --remote --file seed/demo-donations.sql
-- Remove: npx wrangler d1 execute red-hill-rally --remote --command "DELETE FROM donation_students; DELETE FROM donations; DELETE FROM links"
DELETE FROM donation_students;
DELETE FROM donations;
DELETE FROM links;

-- One classroom credit per seeded gift (the classroom race).

-- Family gifts: one gift crediting two or three Rockets, in different
-- classrooms (the race counts each credit).

-- Online business partnerships, one per tier (partner dollars count in the
-- campaign total but not the family-gift tally or the race). Name-only:
-- a logo_id needs a matching object in R2. Earthco merges into its curated
-- listing on the wall; the other three land on the thanks line.

-- Fee cover on about 70% of family gifts, the site's gross-up:
-- (gift + 30¢) / (1 − 2.9%), rounded, minus the gift.
UPDATE donations SET fee_cents = CAST(ROUND((amount_cents + 30) / 0.971) AS INTEGER) - amount_cents
  WHERE partner_tier = '' AND substr(id, -1) IN ('0', '1', '2', '3', '4', '5', '6');
